# --- Auto-push mode (per session): "off" | "basic" | "full" ---
# Governs how much the dashboard is allowed to type into a session's terminal on
# the user's behalf when Codex stops or waits:
#   off   — never write anything at all (no option-picking, no Enter on prompts,
#           no auto /login, no free-form "keep going" messages).
#   basic — auto-pick from Codex's option menus and confirm permission/plan
#           prompts (press Enter), and keep the session logged in. Does NOT type
#           any free-form instructions.
#   full  — everything in "basic" PLUS the autopilot watchdog that composes and
#           types a "keep going" message when Codex pauses waiting on the user
#           before a task is finished. (This was the previous always-on behavior.)
# New sessions default to "basic". Persisted per session to disk.
AUTOPUSH_MODES = ("off", "basic", "full")
AUTOPUSH_DEFAULT = "basic"
AUTOPUSH_MODE_FILE = MESSAGES_DIR / "autopush-mode.json"
_autopush_mode: dict[str, str] = {}


def _get_autopush_mode(session_name: str) -> str:
    m = _autopush_mode.get(session_name, AUTOPUSH_DEFAULT)
    return m if m in AUTOPUSH_MODES else AUTOPUSH_DEFAULT


def _save_autopush_mode():
    try:
        MESSAGES_DIR.mkdir(parents=True, exist_ok=True)
        AUTOPUSH_MODE_FILE.write_text(json.dumps(_autopush_mode))
    except Exception:
        logger.debug("Failed to save autopush-mode map", exc_info=True)


def _load_autopush_mode():
    global _autopush_mode
    try:
        if AUTOPUSH_MODE_FILE.exists():
            data = json.loads(AUTOPUSH_MODE_FILE.read_text())
            if isinstance(data, dict):
                _autopush_mode = {
                    str(k): v for k, v in data.items() if v in AUTOPUSH_MODES
                }
    except Exception:
        logger.debug("Failed to load autopush-mode map", exc_info=True)


def _is_codex_running(session_name: str) -> bool:
    """Return True only when the tmux pane has a live Codex descendant."""
    try:
        result = subprocess.run(
            ["tmux", "display-message", "-t", session_name, "-p", "#{pane_pid}"],
            capture_output=True, text=True, timeout=5
        )
        if result.returncode != 0:
            return False
        pane_pid = (result.stdout or "").strip()
        if not pane_pid.isdigit():
            return False
        pending = [pane_pid]
        seen = {pane_pid}
        for _ in range(64):
            if not pending:
                break
            parent = pending.pop(0)
            children = subprocess.run(
                ["pgrep", "-P", parent], capture_output=True, text=True, timeout=2
            )
            for child in (children.stdout or "").split():
                if child in seen:
                    continue
                seen.add(child)
                pending.append(child)
                try:
                    comm = Path(f"/proc/{child}/comm").read_text().strip().lower()
                    argv = Path(f"/proc/{child}/cmdline").read_bytes().replace(b"\0", b" ").decode(
                        errors="replace"
                    ).lower()
                except Exception:
                    continue
                if comm == "codex" or re.search(r"(?:^|[/\s])codex(?:\s|$)", argv):
                    return True
        return False
    except Exception:
        return False


async def _async_is_codex_running(session_name: str) -> bool:
    """Non-blocking version of _is_codex_running."""
    return await asyncio.to_thread(_is_codex_running, session_name)


async def _ensure_codex_running(session_name: str, log_fn=None, state: dict = None,
                                resume_uuid: str = None) -> bool:
    """Restart a crashed Codex pane and resume its most recent local thread."""
    alog = logging.getLogger("autonomous")
    if await _async_agent_is_running(session_name):
        return True

    msg = f"Codex not running in '{session_name}' — restarting it"
    alog.warning(msg)
    if log_fn and state:
        log_fn(state, msg)

    try:
        # Re-apply clean member auth before relaunch so an accidental /login (which
        # writes stray creds that 401 against the shared key) self-heals on the next
        # start. Picks the right mode: subscription plan if live, else API key.
        try:
            if TEAM_MODE:
                _owner = _find_user_by_id(_load_session_owners().get(session_name, "admin"))
                if _owner and not _is_admin(_owner):
                    _apply_member_auth(_user_codex_config_dir(_owner))
        except Exception:
            logger.debug("Failed to re-apply member auth on relaunch", exc_info=True)
        try:
            await asyncio.to_thread(
                _ensure_codex_auth_with_fallback,
                _session_config_base(session_name),
                True,
            )
        except Exception:
            logger.debug("Failed to validate Codex auth before relaunch", exc_info=True)
        # A crashed pane may have stale shell state from before account
        # isolation was provisioned. Re-export the owner's CODEX_HOME on every
        # recovery before constructing the launch command.
        await asyncio.to_thread(
            _send_profile_export,
            session_name,
            DEFAULT_PROFILE_ID,
        )
        # Codex stores local threads under CODEX_HOME. Resume the newest thread
        # for this working directory instead of opening the interactive picker.
        launch_base = _session_launch_base(session_name)
        launch = _launch_codex_cmd(launch_base, pin_model=True, resume=True)
        # C-u first to discard any stray text left on the crashed shell's prompt
        # line (e.g. a "continue" a watchdog typed before this loop took over).
        await asyncio.to_thread(subprocess.run,
            ["tmux", "send-keys", "-t", session_name, "C-u"],
            capture_output=True, text=True, timeout=5)
        await asyncio.to_thread(subprocess.run,
            ["tmux", "send-keys", "-t", session_name, "-l", launch],
            capture_output=True, text=True, timeout=5)
        await asyncio.to_thread(subprocess.run,
            ["tmux", "send-keys", "-t", session_name, "Enter"],
            capture_output=True, text=True, timeout=5)

        # Wait for codex to start (up to 30s)
        for _ in range(15):
            await asyncio.sleep(2)
            if await _async_agent_is_running(session_name):
                alog.info(f"Codex restarted successfully in '{session_name}'")
                if log_fn and state:
                    log_fn(state, "Codex restarted successfully")
                # Give it a moment to fully initialize
                await asyncio.sleep(5)
                return True

        alog.error(f"Failed to restart Codex in '{session_name}' after 30s")
        if log_fn and state:
            log_fn(state, "Failed to restart Codex after 30s")
        return False
    except Exception as e:
        alog.error(f"Error restarting Codex in '{session_name}': {e}")
        return False


# Backwards-compatible internal names used by newer Grabo browser/recovery code.
_async_is_claude_running = _async_is_codex_running


_background_tasks: list = []


@asynccontextmanager
async def lifespan(_app: FastAPI):
    """Manage startup and shutdown for the Codex Dashboard FastAPI application."""
    # --- Startup ---
    loop = asyncio.get_running_loop()
    loop.set_default_executor(ThreadPoolExecutor(max_workers=20))
    logger.info("Codex Dashboard starting up — port=%s, root_path=%s, auth=%s, openai=%s",
                PORT, ROOT_PATH,
                "enabled" if AUTH_PASS else "disabled",
                "configured" if OPENAI_API_KEY else "missing")
    if not AUTH_PASS:
        logger.warning("TMUX_DASH_PASS is not set — authentication is DISABLED. "
                       "Set TMUX_DASH_PASS to enable auth.")
    if not OPENAI_API_KEY:
        logger.warning("OPENAI_API_KEY is not set — LLM summaries will not work.")
    if not os.environ.get("TMUX_DASH_SECRET"):
        logger.warning("TMUX_DASH_SECRET is not set — auth tokens will be invalidated on restart. "
                       "Set a persistent secret for stable sessions.")
    try:
        migrated_prompts = await asyncio.to_thread(
            _backfill_prompt_audit,
            _load_users(),
        )
        if migrated_prompts:
            logger.info(
                "Prompt audit: migrated %d historical user prompts",
                migrated_prompts,
            )
    except Exception:
        logger.exception("Prompt audit history migration failed")
    try:
        await asyncio.to_thread(_ensure_all_user_browser_sessions)
    except Exception:
        logger.exception("Account browser provisioning failed")
    if TEAM_MODE:
        try:
            _setup_shared_git_config()
            logger.info("Team mode: shared git config applied")
        except Exception:
            logger.debug("shared git config setup failed", exc_info=True)
    sessions = get_tmux_sessions()
    logger.info("Found %d existing tmux sessions", len(sessions))
    # Auto-responder: presses Enter ONLY when the visible pane shows a
    # Codex selection prompt with ❯ directly on a numbered option.
    # The detection refuses to fire when ❯ is followed by free text — that
    # is the user input box and Enter would submit it (the "phantom
    # message" bug). Approves plan/permission prompts hands-free.
    task = asyncio.create_task(_auto_responder_loop())
    _background_tasks.append(task)
    logger.info("Auto-responder background task started")
    _load_simple_watchdog_disabled()
    _load_autopush_mode()
    _restore_default_model_setting()
    simple_watchdog_task = asyncio.create_task(_simple_watchdog_loop())
    _background_tasks.append(simple_watchdog_task)
    logger.info("Simple watchdog started (auto-push overrides for %d sessions)", len(_autopush_mode))

    tmp_watchdog_task = asyncio.create_task(_tmp_watchdog_loop())
    _background_tasks.append(tmp_watchdog_task)
    logger.info("Tmp watchdog started")

    crash_recovery_task = asyncio.create_task(_crash_recovery_loop())
    _background_tasks.append(crash_recovery_task)
    logger.info("Crash-recovery watchdog started")

    model_refresh_task = asyncio.create_task(_model_refresh_loop())
    _background_tasks.append(model_refresh_task)
    logger.info("Model auto-detect started (default=%s, %d models)", DEFAULT_MODEL, len(MODEL_CATALOG))

    resource_guard_task = asyncio.create_task(browser_resource_guard.watchdog(logger=logger))
    _background_tasks.append(resource_guard_task)
    logger.info("Unmanaged-browser resource guard started (shared CPU cap %.2f cores)",
                browser_resource_guard.cpu_quota_percent() / 100.0)

    autopark_task = asyncio.create_task(browser_autopark_watchdog())
    _background_tasks.append(autopark_task)
    logger.info("Browser CPU guard started (nice %d always, freeze >%.0fs idle, "
                "park >%.0fmin idle, threshold %.0f%% of a core)",
                BROWSER_NICE, BROWSER_FREEZE_IDLE_S,
                BROWSER_AUTOPARK_IDLE_S / 60, BROWSER_BUSY_CPU_PCT)

    orphan_reaper_task = asyncio.create_task(orphan_browser_reaper())
    _background_tasks.append(orphan_reaper_task)
    logger.info("Orphan-browser reaper started (nice %d always, kill after %.0fmin orphaned)",
                BROWSER_NICE, ORPHAN_BROWSER_GRACE_S / 60)

    usage_cred_task = asyncio.create_task(usage_credential_watchdog())
    _background_tasks.append(usage_cred_task)
    logger.info("Usage-credential watchdog started (credential present=%s)",
                _usage_credential_ok())

    yield  # Application is running

    # --- Shutdown ---
    logger.info("Codex Dashboard shutting down — cancelling %d background tasks", len(_background_tasks))
    for t in _background_tasks:
        if not t.done():
            t.cancel()
    try:
        _cancel_codex_chatgpt_login()
    except Exception:
        logger.debug("Failed to stop pending Codex login during shutdown", exc_info=True)
    logger.info("Shutdown complete")


app = FastAPI(root_path=ROOT_PATH, lifespan=lifespan)


@app.exception_handler(RequestValidationError)
async def request_validation_error_handler(_request: Request, exc: RequestValidationError):
    """Keep API validation errors compatible with the dashboard's JS client.

    Do not serialize Pydantic's full error structure here: it can include the
    submitted value, which is especially undesirable on credential routes.
    """
    errors = exc.errors()
    message = errors[0].get("msg", "Invalid request") if errors else "Invalid request"
    return JSONResponse({"error": message}, status_code=422)

# --- Auth ---
AUTH_USER = os.environ.get("TMUX_DASH_USER", "admin")
AUTH_PASS = os.environ.get("TMUX_DASH_PASS", "")
AUTH_SECRET = os.environ.get("TMUX_DASH_SECRET", secrets.token_hex(32))
# Cookie name must be UNIQUE per dashboard instance, else two dashboards on the
# same domain (e.g. knowva.ai/tmux + /codex) collide: both set "tmux_auth" at
# Path=/, so logging into one overwrites/invalidates the other's cookie.
AUTH_COOKIE = os.environ.get("TMUX_DASH_COOKIE", "tmux_auth")
_USER_ONLINE_WINDOW_SECONDS = 120
_user_presence: dict[str, float] = {}


def _make_token(user_id: str) -> str:
    sig = hmac.new(AUTH_SECRET.encode(), user_id.encode(), hashlib.sha256).hexdigest()[:24]
    return f"{user_id}:{sig}"


def _check_token(token: str) -> bool:
    if not token or ":" not in token:
        return False
    user_id, sig = token.split(":", 1)
    expected = hmac.new(AUTH_SECRET.encode(), user_id.encode(), hashlib.sha256).hexdigest()[:24]
    return hmac.compare_digest(sig, expected)


# --- Multi-user store ---
# Each user record:
#   { id, username, password_hash, password_salt, role ("admin"|"user"),
#     created_at, last_login }
# Admin (id="admin") is bootstrapped from TMUX_DASH_USER / TMUX_DASH_PASS env vars
# on first run, then writable via the admin UI. Per-user data lives at
# ~/.tmux-dashboard/users/<id>/  (the admin keeps the legacy paths to preserve
# existing messages.json / notes.json / uploads). Per-user Codex config lives
# at ~/.codex-user-<id>/ for non-admin users; admin still uses ~/.codex.
USERS_FILE = MESSAGES_DIR / "users.json"


def _hash_password(password: str, salt: str) -> str:
    return hashlib.sha256((salt + password).encode("utf-8")).hexdigest()


def _new_salt() -> str:
    return secrets.token_hex(16)


def _new_user_id() -> str:
    return "u_" + secrets.token_hex(8)


def _load_users() -> list:
    """Load users from disk. On first run, seed an admin from env vars."""
    if USERS_FILE.exists():
        try:
            data = json.loads(USERS_FILE.read_text())
            users = data.get("users") if isinstance(data, dict) else None
            if isinstance(users, list) and users:
                return users
        except Exception:
            logger.exception("Failed to read %s -- re-seeding", USERS_FILE)
    # Seed admin from env vars (single-user legacy mode)
    salt = _new_salt()
    admin = {
        "id": "admin",
        "username": AUTH_USER or "admin",
        "password_hash": _hash_password(AUTH_PASS or "", salt),
        "password_salt": salt,
        "role": "admin",
        "created_at": time.time(),
        "last_login": 0,
    }
    _save_users([admin])
    return [admin]


def _save_users(users: list):
    try:
        MESSAGES_DIR.mkdir(parents=True, exist_ok=True)
        USERS_FILE.write_text(json.dumps({"users": users}, indent=2))
        try:
            USERS_FILE.chmod(0o600)
        except Exception:
            logger.debug("chmod 600 on users.json failed", exc_info=True)
    except Exception:
        logger.exception("Failed to save users to %s", USERS_FILE)


def _find_user_by_id(user_id: str) -> dict | None:
    for u in _load_users():
        if u.get("id") == user_id:
            return u
    return None


def _find_user_by_username(username: str) -> dict | None:
    for u in _load_users():
        if u.get("username") == username:
            return u
    return None


def _verify_password(user: dict, password: str) -> bool:
    salt = user.get("password_salt", "")
    expected = user.get("password_hash", "")
    candidate = _hash_password(password, salt)
    return bool(expected) and hmac.compare_digest(candidate, expected)


def _user_from_token(token: str | None) -> dict | None:
    """Validate token signature AND look up the user. Returns user dict or None."""
    if not token or not _check_token(token):
        return None
    user_id = token.split(":", 1)[0]
    return _find_user_by_id(user_id)


def _touch_user_presence(user: dict | None) -> None:
    """Record authenticated dashboard activity for lightweight presence."""
    if user and user.get("id"):
        _user_presence[str(user["id"])] = time.time()


def _current_user(request: Request) -> dict | None:
    """Resolve the user for an HTTP request via the tmux_auth cookie.

    When AUTH_PASS is empty (auth disabled), behave as if the admin is logged
    in so every downstream check (`is_admin`, ownership filters, etc.) still
    works without per-call ``if not AUTH_PASS`` branches.
    """
    if not AUTH_PASS:
        admin = _find_user_by_id("admin")
        if admin:
            _touch_user_presence(admin)
            return admin
        synthetic = {
            "id": "admin", "username": AUTH_USER or "admin",
            "role": "admin", "_synthetic": True,
        }
        _touch_user_presence(synthetic)
        return synthetic
    # Stash on request.state to avoid re-loading users.json per request.
    if getattr(request.state, "_current_user_resolved", False):
        return getattr(request.state, "_current_user", None) or None
    cached = getattr(request.state, "_current_user", None)
    base_user = getattr(request.state, "_authenticated_user", None)
    if base_user is None:
        base_user = (cached or None) if cached is not None else _user_from_token(
            request.cookies.get(AUTH_COOKIE)
        )
    user = base_user
    impersonation_token = request.headers.get("X-Tmux-Impersonate", "").strip()
    if impersonation_token:
        target = None
        if _is_admin(base_user):
            target = _user_from_impersonation_session(
                impersonation_token,
                base_user,
            )
        if target:
            request.state._impersonator = base_user
            user = target
        else:
            request.state._invalid_impersonation = True
    request.state._current_user = user or {}
    request.state._current_user_resolved = True
    if user:
        _touch_user_presence(user)
        request.state._presence_touched = True
    return user


def _is_admin(user: dict | None) -> bool:
    return bool(user) and user.get("role") == "admin"


# Initialize the users store on import so the admin always exists.
try:
    _load_users()
except Exception:
    logger.exception("Failed to initialize users.json")


# --- Per-user data dirs ---
# Admin keeps the legacy ~/.tmux-dashboard/ root for backwards compatibility
# with existing messages.json / notes.json / uploads/ on disk. Non-admin users
# are isolated under ~/.tmux-dashboard/users/<user_id>/.
def _user_data_dir(user: dict | None) -> Path:
    if not user or user.get("id") == "admin":
        return MESSAGES_DIR
    d = MESSAGES_DIR / "users" / user["id"]
    d.mkdir(parents=True, exist_ok=True)
    return d


def _user_messages_file(user: dict | None) -> Path:
    return _user_data_dir(user) / "messages.json"


def _user_notes_file(user: dict | None) -> Path:
    return _user_data_dir(user) / "notes.json"


def _user_uploads_dir(user: dict | None) -> Path:
    return _user_data_dir(user) / "uploads"


def _user_codex_config_dir(user: dict | None) -> Path:
    """Where Codex reads AGENTS.md / MEMORY.md / config.toml / skills/
    / projects/ / memory/ for this user. Admin uses ~/.codex (the global root,
    profiles still apply). Non-admin users get a fully isolated dir.
    """
    if not user or user.get("id") == "admin":
        return Path.home() / ".codex"
    return Path.home() / f".codex-user-{user['id']}"


def _member_session_project_dir(user: dict, session_name: str) -> Path:
    """Return and create the only writable project root for a member pane."""
    username = str(user.get("username") or user.get("id") or "")
    if not re.fullmatch(r"[A-Za-z0-9.@_-]{1,128}", username):
        username = str(user.get("id") or "member")
    safe_session = str(session_name or "")
    if not re.fullmatch(r"[A-Za-z0-9_.-]{1,128}", safe_session):
        safe_session = "session-" + hashlib.sha256(
            safe_session.encode("utf-8")
        ).hexdigest()[:16]
    project_dir = PROJECTS_ROOT / username / safe_session
    project_dir.mkdir(parents=True, exist_ok=True)
    return project_dir


def _rewrite_top_level_toml(existing: str, values: dict[str, str | None]) -> str:
    """Replace or remove selected top-level keys without touching TOML tables."""
    out: list[str] = []
    written: set[str] = set()
    in_section = False
    for line in existing.splitlines():
        stripped = line.strip()
        if stripped.startswith("[") and stripped.endswith("]"):
            if not in_section:
                for key, value in values.items():
                    if value is not None and key not in written:
                        out.append(f"{key} = {value}")
                        written.add(key)
            in_section = True
            out.append(line)
            continue
        if not in_section and "=" in stripped and not stripped.startswith("#"):
            key = stripped.split("=", 1)[0].strip()
            if key in values:
                if values[key] is not None and key not in written:
                    out.append(f"{key} = {values[key]}")
                    written.add(key)
                continue
        out.append(line)
    if not in_section:
        if out and out[-1].strip():
            out.append("")
        for key, value in values.items():
            if value is not None and key not in written:
                out.append(f"{key} = {value}")
    return "\n".join(out).rstrip() + "\n"


def _strip_toml_sections(existing: str, prefixes: tuple[str, ...]) -> str:
    """Remove complete TOML tables whose dotted names match a prefix."""
    out: list[str] = []
    skipping = False
    for line in existing.splitlines():
        match = re.match(r"^\s*\[([^\[\]]+)\]\s*$", line)
        if match:
            section = match.group(1).strip()
            skipping = any(
                section == prefix or section.startswith(prefix + ".")
                for prefix in prefixes
            )
        if not skipping:
            out.append(line)
    return "\n".join(out).rstrip() + "\n"


def _set_toml_table_bool(existing: str, section: str, key: str, value: bool) -> str:
    """Upsert one boolean in an existing or new TOML table."""
    lines = existing.splitlines()
    header = f"[{section}]"
    start = next(
        (index for index, line in enumerate(lines) if line.strip() == header),
        None,
    )
    rendered = f"{key} = {'true' if value else 'false'}"
    if start is None:
        if lines and lines[-1].strip():
            lines.append("")
        lines.extend((header, rendered))
        return "\n".join(lines).rstrip() + "\n"
    end = next(
        (
            index
            for index in range(start + 1, len(lines))
            if lines[index].strip().startswith("[")
            and lines[index].strip().endswith("]")
        ),
        len(lines),
    )
    matches = [
        index
        for index in range(start + 1, end)
        if re.match(rf"^\s*{re.escape(key)}\s*=", lines[index])
    ]
    if matches:
        lines[matches[0]] = rendered
        for duplicate in reversed(matches[1:]):
            del lines[duplicate]
    else:
        lines.insert(start + 1, rendered)
    return "\n".join(lines).rstrip() + "\n"


# The GRABO Document Vault (~150k business documents: emails, PDFs, invoices,
# POs, quotes, specs, certificates) lives on grabo-systems and is published at
# grabo.cc/docvault-mcp behind a static bearer key. Codex can speak
# streamable-HTTP to it directly, but only reads a bearer token from its own
# process environment — which would mean exporting the vault key into every
# member's shell, where they can echo it. The local stdio bridge takes the key
# from `mcp_servers.docvault.env` in the member's own config instead.
DOCVAULT_MCP_URL = os.environ.get(
    "DOCVAULT_MCP_URL", "https://grabo.cc/docvault-mcp/mcp")
DOCVAULT_MCP_KEY = os.environ.get("DOCVAULT_MCP_KEY", "")
DOCVAULT_MCP_SCRIPT = Path(__file__).resolve().with_name("docvault_mcp.py")


def _configure_member_codex_isolation(
    cfg_dir: Path,
    user: dict,
    browser: dict | None = None,
) -> bool:
    """Write the complete unattended full-access config for one member."""
    if not user or _is_admin(user):
        return False
    cfg_dir.mkdir(parents=True, exist_ok=True)
    config = cfg_dir / "config.toml"
    existing = config.read_text() if config.exists() else ""
    project_root = PROJECTS_ROOT / str(user.get("username") or user["id"])
    trusted_projects = []
    try:
        trusted_projects = [
            project_root / session_name
            for session_name, owner_id in sorted(
                _load_session_owners().items()
            )
            if owner_id == user.get("id")
            and re.fullmatch(r"[A-Za-z0-9_.-]{1,128}", session_name)
        ]
    except Exception:
        logger.warning(
            "Could not enumerate trusted projects for member %s",
            user.get("id", ""),
            exc_info=True,
        )

    lines = [
        'model = "gpt-5.6-sol"',
        'model_reasoning_effort = "max"',
        'approval_policy = "never"',
        'default_permissions = ":danger-full-access"',
        "",
        "[notice]",
        "hide_full_access_warning = true",
        "",
        "[features]",
        "remote_plugin = false",
        "apps = false",
        "",
        "[tui.model_availability_nux]",
        '"gpt-5.6-sol" = 3',
    ]
    for trusted_project in trusted_projects:
        lines.extend((
            "",
            f'[projects."{_toml_escape(str(trusted_project))}"]',
            'trust_level = "trusted"',
        ))
    lines.extend((
        "",
        "[apps._default]",
        "enabled = false",
    ))
    google_cmd = _google_mcp_command()
    try:
        google_parts = shlex.split(google_cmd)
    except ValueError:
        google_parts = []
    if google_parts:
        google_args = ", ".join(
            f'"{_toml_escape(value)}"' for value in google_parts[1:]
        )
        google_env = [
            (
                'GOOGLE_MCP_CREDENTIALS_DIR = "'
                + _toml_escape(str(CONNECTIONS_DIR / user["id"]))
                + '"'
            ),
            (
                'GOOGLE_OAUTH_CLIENT_FILE = "'
                + _toml_escape(str(GOOGLE_OAUTH_CLIENT_FILE))
                + '"'
            ),
        ]
        dwd_subject = _google_workspace_subject(user)
        if dwd_subject:
            google_env.extend((
                (
                    'GOOGLE_WORKSPACE_DWD_SERVICE_ACCOUNT_FILE = "'
                    + _toml_escape(str(GOOGLE_DWD_SERVICE_ACCOUNT_FILE))
                    + '"'
                ),
                (
                    'GOOGLE_WORKSPACE_DWD_SUBJECT = "'
                    + _toml_escape(dwd_subject)
                    + '"'
                ),
            ))
        lines.extend((
            "",
            "# BEGIN GRABO GOOGLE MCP (managed)",
            "[mcp_servers.google]",
            f'command = "{_toml_escape(google_parts[0])}"',
            f"args = [{google_args}]",
            'default_tools_approval_mode = "approve"',
            "",
            "[mcp_servers.google.env]",
            *google_env,
            "# END GRABO GOOGLE MCP",
        ))
    if google_parts and DOCVAULT_MCP_KEY and DOCVAULT_MCP_SCRIPT.is_file():
        lines.extend((
            "",
            "# BEGIN GRABO DOCVAULT MCP (managed)",
            "[mcp_servers.docvault]",
            f'command = "{_toml_escape(google_parts[0])}"',
            f'args = ["{_toml_escape(str(DOCVAULT_MCP_SCRIPT))}"]',
            'default_tools_approval_mode = "approve"',
            "",
            "[mcp_servers.docvault.env]",
            f'DOCVAULT_MCP_URL = "{_toml_escape(DOCVAULT_MCP_URL)}"',
            f'DOCVAULT_MCP_KEY = "{_toml_escape(DOCVAULT_MCP_KEY)}"',
            "# END GRABO DOCVAULT MCP",
        ))
    updated = "\n".join(lines) + "\n"
    tomllib.loads(updated)
    if updated == existing:
        return False
    _backup_before_dashboard_write(config)
    config.write_text(updated)
    return True


def _ensure_user_codex_config_dir(user: dict):
    """Create + seed a fresh Codex config dir for a non-admin user."""
    if not user or user.get("id") == "admin":
        return
    d = _user_codex_config_dir(user)
    d.mkdir(parents=True, exist_ok=True)
    for sub in ("skills", "projects", "memory", "agents", "commands"):
        (d / sub).mkdir(parents=True, exist_ok=True)
    # Seed minimal files so Codex has something to read.
    codex_md = d / "AGENTS.md"
    if not codex_md.exists():
        codex_md.write_text(
            f"# {user.get('username', user['id'])}'s AGENTS.md\n"
            "Personal notes and project context for this user.\n"
        )
    memory_md = d / "MEMORY.md"
    if not memory_md.exists():
        memory_md.write_text(f"# {user.get('username', user['id'])}'s Memory Index\n")
    config_toml = d / "config.toml"
    existing_config = config_toml.read_text() if config_toml.exists() else ""
    if existing_config:
        desired_config = existing_config
    else:
        desired_config = (
            f'model = "{_CODEX_DEFAULT_MODEL}"\n'
            f'model_reasoning_effort = "{_CODEX_DEFAULT_REASONING_EFFORT}"\n'
            'approval_policy = "never"\n'
        )
    if desired_config != existing_config:
        _backup_before_dashboard_write(config_toml)
        config_toml.write_text(desired_config)
    key = _active_openai_key()
    if key and not (d / "auth.json").exists():
        try:
            _write_codex_api_auth(d, key)
        except Exception:
            logger.debug("Failed to seed Codex auth for user %s", user.get("id"), exc_info=True)
    # Managed member context is independent of the legacy TEAM_MODE flag:
    # multi-account deployments existed before that flag was introduced.
    # Re-apply on every call so existing and newly provisioned accounts
    # self-heal after a host/context change.
    try:
        _sync_global_context_into(codex_md)
        _sync_group_context_into(codex_md, user.get("group", ""))
        _sync_group_skills_into(d, user.get("group", ""))
        _sync_git_rules_into(codex_md)
    except Exception:
        logger.exception(
            "Failed to apply managed context for user %s",
            user.get("id"),
        )
    # TEAM_MODE additionally shares Codex authentication and applies the
    # compatibility guard/model setup used by older team deployments.
    if TEAM_MODE:
        try:
            _apply_member_auth(d)
        except Exception:
            logger.exception("Failed to apply team-mode setup for user %s", user.get("id"))
    try:
        _configure_member_codex_isolation(d, user)
    except Exception:
        logger.exception("Failed to configure Codex for user %s", user.get("id"))


# Compatibility aliases used throughout the newer Grabo team/admin code.
_user_claude_config_dir = _user_codex_config_dir
_ensure_user_claude_config_dir = _ensure_user_codex_config_dir


# --- Session ownership ---
SESSION_OWNERS_FILE = MESSAGES_DIR / "session_owners.json"
_session_owners_cache: dict[str, str] | None = None


def _load_session_owners() -> dict[str, str]:
    global _session_owners_cache
    if _session_owners_cache is not None:
        return _session_owners_cache
    try:
        if SESSION_OWNERS_FILE.exists():
            data = json.loads(SESSION_OWNERS_FILE.read_text())
            if isinstance(data, dict):
                _session_owners_cache = {str(k): str(v) for k, v in data.items()}
                return _session_owners_cache
    except Exception:
        logger.debug("Failed to load session owners", exc_info=True)
    _session_owners_cache = {}
    return _session_owners_cache


def _save_session_owners():
    try:
        MESSAGES_DIR.mkdir(parents=True, exist_ok=True)
        SESSION_OWNERS_FILE.write_text(json.dumps(_load_session_owners(), indent=2))
    except Exception:
        logger.debug("Failed to save session owners", exc_info=True)


def _session_owner_id(session_name: str) -> str:
    """Return the owner user_id for a session. Pre-existing sessions with no
    recorded owner default to the admin."""
    owners = _load_session_owners()
    return owners.get(session_name, "admin")


def _set_session_owner(session_name: str, user_id: str):
    owners = _load_session_owners()
    owners[session_name] = user_id
    _save_session_owners()


def _clear_session_owner(session_name: str):
    owners = _load_session_owners()
    if session_name in owners:
        owners.pop(session_name, None)
        _save_session_owners()


def _user_for_session(session_name: str) -> dict | None:
    """Find the user record that owns this session, falling back to admin."""
    owner_id = _session_owner_id(session_name)
    user = _find_user_by_id(owner_id) or _find_user_by_id("admin")
    return user


def _user_can_access_session(user: dict | None, session_name: str) -> bool:
    """Admins see everything. Regular users only see sessions they own."""
    if _is_admin(user):
        return True
    if not user:
        return False
    return _session_owner_id(session_name) == user["id"]


