@app.get("/api/sessions/{session_name}/raw")
async def api_raw_output(session_name: str):
    """Return raw scrollback content for a session."""
    _, sess = _find_session(session_name)
    if not sess:
        return JSONResponse({"error": "Session not found"}, status_code=404)
    raw = await asyncio.to_thread(capture_pane_full, session_name)
    activity = await async_detect_activity(session_name)
    pane_width = await asyncio.to_thread(get_pane_width, session_name)
    return JSONResponse({
        "name": session_name,
        "raw": raw,
        "lines": len(raw.split("\n")),
        "pane_width": pane_width,
        "activity_status": activity["status"],
        "activity_command": activity["command"],
        "activity_detail": activity["detail"],
    })


def _visible_pane_hash(session_name: str) -> str:
    """Cheap fingerprint of the visible tmux pane (alternate-screen aware).

    capture-pane without -S only returns the visible area, which Codex
    redraws into via its TUI even when history_size never grows. We hash that
    so the client can detect TUI redraws as content changes.
    """
    try:
        result = subprocess.run(
            ["tmux", "capture-pane", "-t", session_name, "-p"],
            capture_output=True, text=True, timeout=3,
        )
        if result.returncode == 0:
            return hashlib.md5(result.stdout.encode("utf-8", "replace")).hexdigest()
    except Exception:
        logger.debug("Failed to hash visible pane for '%s'", session_name, exc_info=True)
    return ""


@app.get("/api/sessions/{session_name}/raw-tail")
async def api_raw_tail(session_name: str, known_lines: int = 0, last_hash: str = ""):
    """Return delta output since the client's last known line count.

    Also detects in-place TUI redraws (Codex's alternate screen) by
    hashing the visible pane — a hash mismatch forces a full capture even when
    scrollback length is unchanged.
    """
    _, found = _find_session(session_name)
    if not found:
        return JSONResponse({"error": "Session not found"}, status_code=404)

    pos = await asyncio.to_thread(get_pane_position, session_name)
    current_total = pos["total_lines"]
    vis_hash = await asyncio.to_thread(_visible_pane_hash, session_name)
    pane_width = await asyncio.to_thread(get_pane_width, session_name)

    # First load or session reset → full capture
    if known_lines <= 0 or known_lines > current_total:
        raw = await asyncio.to_thread(capture_pane_full, session_name)
        return JSONResponse({
            "mode": "full",
            "raw": raw,
            "total_lines": len(raw.split("\n")),
            "pane_total": current_total,
            "pane_width": pane_width,
            "visible_hash": vis_hash,
        })

    # No scrollback growth, but visible content changed (TUI redraw) → full
    if current_total <= known_lines:
        if last_hash and vis_hash and last_hash != vis_hash:
            raw = await asyncio.to_thread(capture_pane_full, session_name)
            return JSONResponse({
                "mode": "full",
                "raw": raw,
                "total_lines": len(raw.split("\n")),
                "pane_total": current_total,
                "pane_width": pane_width,
                "visible_hash": vis_hash,
            })
        return JSONResponse({
            "mode": "none",
            "total_lines": known_lines,
            "pane_total": current_total,
            "pane_width": pane_width,
            "visible_hash": vis_hash,
        })

    # Delta: capture only the new lines + small overlap for dedup
    overlap = 5
    lines_from_end = (current_total - known_lines) + overlap
    raw = await asyncio.to_thread(capture_pane_recent, session_name, lines_from_end)
    return JSONResponse({
        "mode": "delta",
        "raw": raw,
        "total_lines": current_total,
        "pane_total": current_total,
        "pane_width": pane_width,
        "overlap": overlap,
        "visible_hash": vis_hash,
    })


class CreateSession(BaseModel):
    name: str = ""
    backend: str = ""     # "claude" | "codex"; blank = the dashboard default


def _is_valid_session_name(name: str) -> bool:
    return bool(name and len(name) <= 128 and re.fullmatch(r"[A-Za-z0-9_.-]+", name))


@app.post("/api/sessions/create")
async def api_create_session(request: Request, body: CreateSession):
    """Create a new tmux session."""
    user = _current_user(request)
    name = body.name.strip()
    if name:
        # Validate name: alphanumeric, dash, underscore only
        if not _is_valid_session_name(name):
            return JSONResponse(
                {"error": "Invalid name. Use up to 128 letters, numbers, dots, dashes, or underscores."},
                status_code=400,
            )
        existing = [s["name"] for s in get_tmux_sessions()]
        if name in existing:
            return JSONResponse({"error": f"Session '{name}' already exists."}, status_code=409)
        if name in _get_all_tmux_session_names():
            return JSONResponse(
                {"error": f"A tmux session named '{name}' already exists but is hidden from this dashboard."},
                status_code=409,
            )
    # Which backend is this session? An explicit choice wins, then the
    # dashboard default. Everything below — readiness, auth, the launch command
    # and the per-member config home — follows from this one decision.
    spec = get_provider(body.backend) if body.backend else DEFAULT_PROVIDER
    if spec not in enabled_providers():
        return JSONResponse(
            {"error": f"{spec.label} is not installed on this host."}, status_code=503)
    if spec.key == "codex":
        # A stored API key is the recovery credential when a managed ChatGPT
        # token can no longer be refreshed. Validate/switch before launching.
        await asyncio.to_thread(_ensure_codex_auth_with_fallback, CODEX_HOME, True)
        ready, reason, details = await asyncio.to_thread(_codex_cli_readiness)
        if not ready:
            return JSONResponse(
                {"error": f"Codex launch blocked: {reason}", "codex": details},
                status_code=503,
            )
    try:
        cmd = ["tmux", "new-session", "-d"]
        if name:
            cmd += ["-s", name]
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=5)
        if result.returncode != 0:
            return JSONResponse({"error": result.stderr.strip() or "Failed to create session"}, status_code=500)
        # Find the new session name (if auto-named)
        sessions = get_tmux_sessions()
        if name:
            created = name
        else:
            created = sessions[-1]["name"] if sessions else "unknown"
        # Record session ownership. If auth is disabled, fall back to admin.
        owner_id = user["id"] if user else "admin"
        _set_session_owner(created, owner_id)
        # Export project-publishing convention env vars so Codex can publish to
        # the configured public dashboard URL reliably (see global context).
        try:
            _owner_name = (user.get("username") if user else AUTH_USER) or "admin"
            _proj_dir = str(PROJECTS_ROOT / _owner_name / created)
            _pub_base = PUB_URL
            # Per-user git identity: every member shares ONE OS user, so set the
            # commit author/committer per session → commits are attributed to the
            # right person. Push still uses the box's shared GitHub creds.
            _git_email = f"{_owner_name}@{GIT_EMAIL_DOMAIN}"
            _exports = ("export DASH_USER={} DASH_SESSION={} DASH_PROJECT_DIR={} DASH_PROJECT_URL={} "
                        "GIT_AUTHOR_NAME={} GIT_AUTHOR_EMAIL={} GIT_COMMITTER_NAME={} GIT_COMMITTER_EMAIL={}".format(
                shlex.quote(_owner_name), shlex.quote(created),
                shlex.quote(_proj_dir), shlex.quote(f"{_pub_base}/{_owner_name}/{created}"),
                shlex.quote(_owner_name), shlex.quote(_git_email),
                shlex.quote(_owner_name), shlex.quote(_git_email)))
            subprocess.run(["tmux", "send-keys", "-t", created, "-l", _exports], capture_output=True, text=True, timeout=5)
            subprocess.run(["tmux", "send-keys", "-t", created, "Enter"], capture_output=True, text=True, timeout=5)
        except Exception:
            logger.debug("Failed to export DASH_* project env for %s", created, exc_info=True)
        # Admins don't receive the member global block, so give them the projects
        # convention directly (members already have it in their global context).
        try:
            if TEAM_MODE and _is_admin(user):
                acfg = _user_codex_config_dir(user)
                _sync_projects_note_into(acfg / "AGENTS.md")
                _ensure_google_mcp(acfg, user)
                _ensure_docvault_mcp(acfg)
                _set_team_model_effort(acfg)
                _sync_git_rules_into(acfg / "AGENTS.md")
        except Exception:
            logger.debug("Failed to harden admin team config", exc_info=True)
        # For non-admin users, force their isolated CODEX_HOME so every Codex
        # invocation in this pane reads from the user's private config.
        if user and not _is_admin(user):
            try:
                if not _send_profile_export(created, DEFAULT_PROFILE_ID):
                    raise RuntimeError("could not configure member pane")
            except Exception:
                logger.exception("Failed to set per-user CODEX_HOME for '%s'", created)
        # Authenticate non-admin sessions from the shared Codex auth file.
        # Admin sessions use the default ~/.codex login directly.
        if user and not _is_admin(user):
            _session_auth_mode[created] = _apply_member_auth(
                _user_agent_config_dir(user, spec))
        else:
            try:
                mode = json.loads((CODEX_HOME / "auth.json").read_text()).get("auth_mode")
            except Exception:
                mode = ""
            _session_auth_mode[created] = (
                "subscription" if mode == "chatgpt"
                else "api" if mode == "apikey"
                else "unconfigured"
            )
        # Optionally launch a command in the new session. Team members keep the
        # model pinned in their isolated Codex config; admins use the dashboard default.
        _record_session_backend(created, spec.key)
        # Give the session its context before the CLI starts reading it:
        # instructions, skills, prompts, MCP servers, policy, runtime tier and
        # the memory digest, all rendered from agentctx/core for THIS backend.
        if agentctx is not None:
            try:
                session_cwd = get_session_cwd(created) or ""
                ctx_home = _agent_home_for(user, spec)
                prep = agentctx.prepare_session(
                    spec.key, ctx_home, session_cwd, session_name=created,
                    render_env={spec.config_home_env: str(ctx_home)})
                if prep.get("errors"):
                    logger.warning("agentctx for '%s': %s", created, prep["errors"])
                # Without these the event stream cannot attribute a line to a
                # session or a backend, which makes it useless for the watchdogs.
                subprocess.run(
                    ["tmux", "send-keys", "-t", created, "-l",
                     agentctx.export_lines(spec.key, created, session_cwd)],
                    capture_output=True, text=True, timeout=5)
                subprocess.run(["tmux", "send-keys", "-t", created, "Enter"],
                               capture_output=True, text=True, timeout=5)
            except Exception:
                logger.exception("agentctx session preparation failed for '%s'", created)
        if NEW_SESSION_CMD or spec is not DEFAULT_PROVIDER:
            _pin_model = not (user and not _is_admin(user))
            subprocess.run(
                ["tmux", "send-keys", "-t", created, "-l",
                 _agent_launch_cmd(_session_launch_base(created, user, spec),
                                   pin_model=_pin_model, provider=spec)],
                capture_output=True, text=True, timeout=5
            )
            subprocess.run(
                ["tmux", "send-keys", "-t", created, "Enter"],
                capture_output=True, text=True, timeout=5
            )
        logger.info("Session created: '%s' (auth_mode=%s)", created, _session_auth_mode.get(created, "unknown"))
        return JSONResponse({"ok": True, "name": created})
    except Exception as e:
        logger.error("Failed to create session '%s': %s", name, e)
        return JSONResponse({"error": str(e)}, status_code=500)


@app.delete("/api/sessions/{session_name}")
async def api_delete_session(request: Request, session_name: str):
    """Kill a tmux session and all its child processes."""
    user = _current_user(request)
    _, sess = _find_session_for_user(session_name, user)
    if not sess:
        return JSONResponse({"error": "Session not found"}, status_code=404)
    try:
        # First, find and kill all processes in the session's panes.
        # This ensures Codex (node) processes are terminated cleanly
        # before the tmux session is destroyed.
        try:
            # Get all pane PIDs in this session
            pane_result = subprocess.run(
                ["tmux", "list-panes", "-t", session_name, "-F", "#{pane_pid}"],
                capture_output=True, text=True, timeout=5
            )
            if pane_result.returncode == 0:
                pane_pids = [int(pid) for pid in pane_result.stdout.split() if pid.isdigit()]
                if pane_pids:
                    cleanup = await asyncio.to_thread(
                        browser_resource_guard.terminate_descendants, pane_pids
                    )
                    if not cleanup.get("ok"):
                        logger.warning("Session '%s' descendant cleanup left pids %s",
                                       session_name, cleanup.get("remaining", []))
                    else:
                        logger.info("Session '%s' descendant cleanup targeted %d process(es)",
                                    session_name, cleanup.get("targeted", 0))
        except Exception:
            logger.debug("Process cleanup failed for session '%s' — kill-session will still clean up", session_name, exc_info=True)

        result = subprocess.run(
            ["tmux", "kill-session", "-t", session_name],
            capture_output=True, text=True, timeout=5
        )
        if result.returncode != 0:
            return JSONResponse({"error": result.stderr.strip() or "Failed to kill session"}, status_code=500)
        # Clean up all per-session state from global dicts
        cache.pop(session_name, None)
        _auto_approve_sent.pop(session_name, None)
        _pane_stability.pop(session_name, None)
        _activity_state.pop(session_name, None)
        _session_stats_cache.pop(session_name, None)
        _auto_respond_cooldown.pop(session_name, None)
        _session_auth_mode.pop(session_name, None)
        _forget_session_backend(session_name)
        _simple_watchdog_state.pop(session_name, None)
        _simple_watchdog_log.pop(session_name, None)
        _crash_recovery_state.pop(session_name, None)
        _seen_claude_running.discard(session_name)
        if session_name in _simple_watchdog_disabled:
            _simple_watchdog_disabled.discard(session_name)
            _save_simple_watchdog_disabled()
        # Drop the ownership record. Messages/notes are kept on disk so they
        # show up in the user's History tab even after the live session dies.
        _clear_session_owner(session_name)
        logger.info("Session deleted: '%s'", session_name)
        return JSONResponse({"ok": True, "killed": session_name})
    except Exception as e:
        return JSONResponse({"error": str(e)}, status_code=500)


def get_session_cwd(session_name: str) -> str:
    """Get the current working directory of a tmux session's active pane."""
    try:
        result = subprocess.run(
            ["tmux", "display-message", "-t", session_name, "-p", "#{pane_current_path}"],
            capture_output=True, text=True, timeout=5
        )
        if result.returncode == 0 and result.stdout.strip():
            return result.stdout.strip()
    except Exception:
        logger.debug("Failed to get CWD for session '%s'", session_name, exc_info=True)
    return ""


UPLOADS_DIR = MESSAGES_DIR / "uploads"
PENDING_UPLOADS_FILE = MESSAGES_DIR / "pending_uploads.json"


def _session_upload_key(session_name: str, sess: Optional[dict] = None) -> str:
    """Stable per-session-INSTANCE key for the uploads dir.

    tmux session names get reused — kill "test", create "test" again — so keying
    uploads on the name alone hands the new session the old one's files. tmux's
    #{session_created} timestamp is unique per instance, so "<name>-<created>"
    stays distinct across reuse. Falls back to the bare name if tmux didn't
    report a creation time.
    """
    safe = re.sub(r"[^A-Za-z0-9._-]", "_", session_name).strip("._-") or "session"
    if sess is None:
        _, sess = _find_session(session_name)
    created = str((sess or {}).get("created") or "").strip()
    return f"{safe}-{created}" if created.isdigit() else safe


def _session_uploads_dir(session_name: str, sess: Optional[dict] = None,
                         create: bool = True) -> Path:
    """Uploads dir for one session instance, adopting the legacy bare-name dir."""
    key = _session_upload_key(session_name, sess)
    target = UPLOADS_DIR / key
    legacy = UPLOADS_DIR / session_name
    # One-time adoption: uploads made before this scheme lived in
    # uploads/<name>/. Hand them to the first instance that asks rather than
    # orphaning them.
    if key != session_name and not target.exists() and legacy.is_dir():
        try:
            legacy.rename(target)
        except Exception:
            logger.debug("Could not migrate legacy uploads dir %s", legacy, exc_info=True)
    if create:
        target.mkdir(parents=True, exist_ok=True)
    return target


def _add_pending_upload(key: str, path: str, size: int):
    """Queue an upload to be named in the session's NEXT outgoing message."""
    data = _read_json_file(PENDING_UPLOADS_FILE)
    items = [i for i in data.get(key, []) if i.get("path") != path]
    items.append({"path": path, "size": size, "ts": time.time()})
    data[key] = items[-20:]
    _write_json_file(PENDING_UPLOADS_FILE, data)


def _drop_pending_upload(key: str, path: str):
    """Forget a queued upload (the file was deleted before it was ever sent)."""
    data = _read_json_file(PENDING_UPLOADS_FILE)
    items = [i for i in data.get(key, []) if i.get("path") != path]
    if items:
        data[key] = items
    else:
        data.pop(key, None)
    _write_json_file(PENDING_UPLOADS_FILE, data)


def _peek_pending_uploads(key: str) -> set:
    return {i.get("path") for i in _read_json_file(PENDING_UPLOADS_FILE).get(key, [])}


def _take_pending_uploads(key: str) -> list:
    """Pop the queued uploads — they are about to be named in a message."""
    data = _read_json_file(PENDING_UPLOADS_FILE)
    items = data.pop(key, [])
    if items:
        _write_json_file(PENDING_UPLOADS_FILE, data)
    return items


def _format_upload_preamble(items: list) -> str:
    """Header prepended to a message so the agent knows which files it names."""
    if not items:
        return ""
    label = "file" if len(items) == 1 else "files"
    lines = [f"[The user just uploaded {len(items)} {label} to this session; "
             "the message below refers to them:]"]
    for i in items:
        n = i.get("size") or 0
        size = f"{n} B" if n < 1024 else (f"{n / 1024:.1f} KB" if n < 1024 * 1024
                                          else f"{n / 1048576:.1f} MB")
        lines.append(f"  {i.get('path')} ({size})")
    return "\n".join(lines) + "\n\n"


@app.post("/api/sessions/{session_name}/upload")
async def api_upload_file(session_name: str, file: UploadFile = File(...)):
    """Upload a file to a session-specific uploads dir; record only in this session's chat history."""
    _, sess = _find_session(session_name)
    if not sess:
        return JSONResponse({"error": "Session not found"}, status_code=404)

    # Sanitize filename — keep only the basename
    filename = os.path.basename(file.filename or "upload")
    if not filename or filename.startswith("."):
        return JSONResponse({"error": "Invalid filename"}, status_code=400)

    # Save to this session INSTANCE's uploads dir — see _session_upload_key for
    # why the tmux name alone isn't enough.
    key = _session_upload_key(session_name, sess)
    uploads_dir = _session_uploads_dir(session_name, sess)
    dest = str(uploads_dir / filename)
    try:
        content = await file.read()
        max_size = 50 * 1024 * 1024  # 50 MB
        if len(content) > max_size:
            return JSONResponse({"error": f"File too large ({len(content) / 1024 / 1024:.1f} MB). Max is 50 MB."}, status_code=413)
        with open(dest, "wb") as f:
            f.write(content)
        # Queue it so the next message the user sends names this exact path —
        # otherwise the agent in the pane never learns the upload happened.
        _add_pending_upload(key, dest, len(content))
        # Per-session record only — never touch the project CLAUDE.md, which is
        # shared across every session running in the same cwd.
        size_kb = len(content) / 1024
        note = f"Uploaded {filename} ({size_kb:.1f} KB) to {dest}"
        now = time.time()
        entry = cache.setdefault(session_name, {})
        if "messages" not in entry:
            entry["messages"] = _load_session_messages(session_name)
        entry["messages"].append({"role": "user", "text": note, "ts": now})
        _save_messages()
        return JSONResponse({"ok": True, "path": dest, "size": len(content)})
    except Exception as e:
        return JSONResponse({"error": str(e)}, status_code=500)


@app.get("/api/sessions/{session_name}/uploads")
async def api_list_uploads(session_name: str):
    """List previously uploaded files for a session (newest first)."""
    _, sess = _find_session(session_name)
    if not sess:
        return JSONResponse({"error": "Session not found"}, status_code=404)
    uploads_dir = _session_uploads_dir(session_name, sess, create=False)
    pending = _peek_pending_uploads(_session_upload_key(session_name, sess))
    files = []
    if uploads_dir.exists():
        for entry in uploads_dir.iterdir():
            if not entry.is_file():
                continue
            try:
                st = entry.stat()
                files.append({
                    "name": entry.name,
                    "path": str(entry),
                    "size": st.st_size,
                    "mtime": st.st_mtime,
                    # True = not yet named in a message; the next send announces it.
                    "pending": str(entry) in pending,
                })
            except Exception:
                continue
    files.sort(key=lambda f: f["mtime"], reverse=True)
    return JSONResponse({"files": files})


@app.delete("/api/sessions/{session_name}/uploads/{filename}")
async def api_delete_upload(session_name: str, filename: str):
    """Remove a previously uploaded file from the session uploads dir."""
    _, sess = _find_session(session_name)
    if not sess:
        return JSONResponse({"error": "Session not found"}, status_code=404)
    safe_name = os.path.basename(filename)
    if not safe_name or safe_name.startswith("."):
        return JSONResponse({"error": "Invalid filename"}, status_code=400)
    target = _session_uploads_dir(session_name, sess, create=False) / safe_name
    try:
        if target.exists() and target.is_file():
            target.unlink()
            _drop_pending_upload(_session_upload_key(session_name, sess), str(target))
            return JSONResponse({"ok": True})
        return JSONResponse({"error": "File not found"}, status_code=404)
    except Exception as e:
        return JSONResponse({"error": str(e)}, status_code=500)


# --- AGENTS.md viewer/editor ---

@app.get("/api/sessions/{session_name}/codex-md")
async def api_get_codex_md(session_name: str):
    """Read AGENTS.md from the session's working directory and home dir."""
    _, sess = _find_session(session_name)
    if not sess:
        return JSONResponse({"error": "Session not found"}, status_code=404)
    cwd = get_session_cwd(session_name)
    results = []
    # Check session CWD
    if cwd:
        md_path = os.path.join(cwd, "AGENTS.md")
        content = ""
        if os.path.exists(md_path):
            try:
                with open(md_path) as f:
                    content = f.read()
            except Exception:
                logger.debug("Failed to read AGENTS.md at %s", md_path, exc_info=True)
        results.append({"path": md_path, "content": content, "exists": os.path.exists(md_path), "label": "Project"})
    # Check home dir
    home_md = os.path.join(str(Path.home()), "AGENTS.md")
    home_content = ""
    if os.path.exists(home_md):
        try:
            with open(home_md) as f:
                home_content = f.read()
        except Exception:
            logger.debug("Failed to read global AGENTS.md at %s", home_md, exc_info=True)
    results.append({"path": home_md, "content": home_content, "exists": os.path.exists(home_md), "label": "Global"})
    return JSONResponse({"files": results, "cwd": cwd or ""})


class SaveCodexMd(BaseModel):
    path: str
    content: str


@app.post("/api/sessions/{session_name}/codex-md")
async def api_save_codex_md(session_name: str, body: SaveCodexMd):
    """Save AGENTS.md to the specified path."""
    _, sess = _find_session(session_name)
    if not sess:
        return JSONResponse({"error": "Session not found"}, status_code=404)
    # Safety: only allow writing AGENTS.md files within home directory
    if not body.path.endswith("AGENTS.md"):
        return JSONResponse({"error": "Can only write AGENTS.md files"}, status_code=400)
    real_path = os.path.realpath(body.path)
    home_dir = str(Path.home())
    if not real_path.startswith(home_dir + "/") and real_path != home_dir:
        return JSONResponse({"error": "Path must be within home directory"}, status_code=403)
    if not real_path.endswith("/AGENTS.md"):
        return JSONResponse({"error": "Invalid path after resolution"}, status_code=400)
    try:
        os.makedirs(os.path.dirname(real_path), exist_ok=True)
        _backup_before_dashboard_write(Path(real_path))
        with open(real_path, "w") as f:
            f.write(body.content)
        return JSONResponse({"ok": True, "path": real_path})
    except Exception as e:
        return JSONResponse({"error": str(e)}, status_code=500)


# --- seam: the session's instruction file ---------------------------------
#  Claude reads CLAUDE.md, Codex reads AGENTS.md. Same editor, same two scopes
#  (project + global); the route resolves which filename this session's backend
#  actually loads, so the "Project context" tab is right for either.

@app.get("/api/sessions/{session_name}/context-md")
async def api_get_context_md(session_name: str):
    spec = _session_provider(session_name)
    resp = (await api_get_claude_md(session_name) if spec.key == "claude"
            else await api_get_codex_md(session_name))
    return _with_context_filename(resp, spec)


@app.post("/api/sessions/{session_name}/context-md")
async def api_save_context_md(session_name: str, body: SaveCodexMd):
    spec = _session_provider(session_name)
    if spec.key == "claude":
        return await api_save_claude_md(session_name, SaveClaudeMd(path=body.path,
                                                                   content=body.content))
    return await api_save_codex_md(session_name, body)


def _with_context_filename(resp, spec):
    """Tell the editor which filename it is looking at, without re-reading it."""
    try:
        payload = json.loads(bytes(resp.body).decode())
        payload["filename"] = spec.context_filename
        payload["backend"] = spec.key
        return JSONResponse(payload, status_code=resp.status_code)
    except Exception:
        return resp




# The global AGENTS.md is edited through /api/context-files, alongside the
# reference docs it links to, so the whole set is visible in one place.


# --- Session-scoped auto-memory (project MEMORY.md + sibling topic files) ---
# Codex reads MEMORY.md from `<CODEX_HOME>/projects/<encoded-cwd>/memory/MEMORY.md`,
# where the encoded path replaces `/` and `_` with `-`. We mirror that here.

def _encode_project_path(cwd: str) -> str:
    """Mirror Codex's project-dir encoding: replace `/` and `_` with `-`."""
    return (cwd or "").replace("/", "-").replace("_", "-")


def _session_config_base(session_name: str) -> Path:
    """Resolve the config home a session actually uses.

    Backend-aware: the same member has one home per backend
    (``~/.codex-user-<id>`` / ``~/.claude-user-<id>``), so switching a session
    from Codex to Claude reads and writes the right context, skills and MCP
    config instead of silently landing in the other backend's tree. Admin
    sessions use the dashboard's own home for that backend.
    """
    spec = _session_provider(session_name)
    owner = _user_for_session(session_name)
    if owner and not _is_admin(owner):
        return _user_agent_config_dir(owner, spec)
    return CLAUDE_HOME if spec.key == "claude" else CODEX_HOME


def _session_memory_dir(session_name: str) -> tuple[Path, str, str]:
    """Resolve the project memory dir for a session.
    Returns (memory_dir_path, cwd, profile_id). memory_dir_path may not exist yet.

    NOTE this is the dashboard's own per-project store. Claude Code reads it
    directly; Codex does not — Codex reads one global MEMORY.md — so for a Codex
    session the bridge in agentctx/memory_sync.py is what actually gets these
    notes in front of the agent. Writing here is never enough on its own.
    """
    cwd = get_session_cwd(session_name) or ""
    profile_id = _get_session_profile_id(session_name)
    encoded = _encode_project_path(cwd)
    base = _session_config_base(session_name)
    mem_dir = base / "projects" / encoded / "memory"
    return mem_dir, cwd, profile_id


_MEMORY_EXTRA_RE = re.compile(r"^[A-Za-z0-9._-]+\.md$")


def _sanitize_memory_filename(name: str) -> str:
    name = os.path.basename(name or "")
    if not _MEMORY_EXTRA_RE.match(name):
        return ""
    return name


@app.get("/api/sessions/{session_name}/memory-md")
async def api_get_session_memory_md(session_name: str):
    """Read the auto-memory MEMORY.md for the session's Codex home and cwd."""
    _, sess = _find_session(session_name)
    if not sess:
        return JSONResponse({"error": "Session not found"}, status_code=404)
    mem_dir, cwd, profile_id = _session_memory_dir(session_name)
    if not cwd:
        return JSONResponse({"error": "Could not determine session cwd"}, status_code=400)
    mpath = mem_dir / "MEMORY.md"
    content = ""
    if mpath.exists():
        try:
            content = mpath.read_text()
        except Exception:
            logger.debug("Failed to read session MEMORY.md at %s", mpath, exc_info=True)
    return JSONResponse({
        "path": str(mpath), "content": content, "exists": mpath.exists(),
        "dir": str(mem_dir), "cwd": cwd, "profile_id": profile_id,
    })


@app.post("/api/sessions/{session_name}/memory-md")
async def api_save_session_memory_md(session_name: str, body: SaveCodexMd):
    """Save the auto-memory MEMORY.md (creates dir if missing)."""
    _, sess = _find_session(session_name)
    if not sess:
        return JSONResponse({"error": "Session not found"}, status_code=404)
    mem_dir, cwd, _profile_id = _session_memory_dir(session_name)
    if not cwd:
        return JSONResponse({"error": "Could not determine session cwd"}, status_code=400)
    mpath = mem_dir / "MEMORY.md"
    # Path safety: ensure mpath is inside mem_dir which is inside the profile dir
    try:
        if not str(mpath.resolve().parent) == str(mem_dir.resolve()):
            return JSONResponse({"error": "Invalid path"}, status_code=400)
    except Exception:
        pass
    real_target = os.path.realpath(body.path)
    if real_target != os.path.realpath(str(mpath)):
        return JSONResponse({"error": "Path mismatch"}, status_code=400)
    try:
        mem_dir.mkdir(parents=True, exist_ok=True)
        mpath.write_text(body.content)
        return JSONResponse({"ok": True, "path": str(mpath)})
    except Exception:
        logger.exception("Failed to save session MEMORY.md")
        return JSONResponse({"error": "Failed to save"}, status_code=500)


@app.get("/api/sessions/{session_name}/memory-extras")
async def api_list_session_memory_extras(session_name: str):
    """List sibling .md topic files alongside MEMORY.md (excludes MEMORY.md itself)."""
    _, sess = _find_session(session_name)
    if not sess:
        return JSONResponse({"error": "Session not found"}, status_code=404)
    mem_dir, cwd, _profile_id = _session_memory_dir(session_name)
    files = []
    if mem_dir.exists():
        for p in sorted(mem_dir.iterdir()):
            if not (p.is_file() and p.suffix == ".md"):
                continue
            if p.name.upper() == "MEMORY.MD":
                continue
            try:
                files.append({"name": p.name, "content": p.read_text(),
                              "size": p.stat().st_size})
            except Exception:
                logger.debug("Failed to read memory topic %s", p, exc_info=True)
    return JSONResponse({"files": files, "dir": str(mem_dir), "cwd": cwd})


@app.post("/api/sessions/{session_name}/memory-extras")
async def api_save_session_memory_extra(session_name: str, body: SkillFileBody):
    """Create or update a topic file in the session's memory dir."""
    _, sess = _find_session(session_name)
    if not sess:
        return JSONResponse({"error": "Session not found"}, status_code=404)
    mem_dir, cwd, _profile_id = _session_memory_dir(session_name)
    if not cwd:
        return JSONResponse({"error": "Could not determine session cwd"}, status_code=400)
    fname = _sanitize_memory_filename(body.name)
    if not fname:
        return JSONResponse({"error": "Invalid filename. Use alphanumerics/dots/dashes/underscores ending in .md."}, status_code=400)
    if fname.upper() == "MEMORY.MD":
        return JSONResponse({"error": "MEMORY.md has its own editor."}, status_code=400)
    mem_dir.mkdir(parents=True, exist_ok=True)
    fpath = mem_dir / fname
    if not str(fpath.resolve()).startswith(str(mem_dir.resolve()) + os.sep):
        return JSONResponse({"error": "Invalid path"}, status_code=400)
    try:
        fpath.write_text(body.content)
        return JSONResponse({"ok": True, "name": fname})
    except Exception:
        logger.exception("Failed to save memory topic file")
        return JSONResponse({"error": "Failed to save file"}, status_code=500)


@app.delete("/api/sessions/{session_name}/memory-extras/{filename}")
async def api_delete_session_memory_extra(session_name: str, filename: str):
    _, sess = _find_session(session_name)
    if not sess:
        return JSONResponse({"error": "Session not found"}, status_code=404)
    mem_dir, _cwd, _profile_id = _session_memory_dir(session_name)
    fname = _sanitize_memory_filename(filename)
    if not fname or fname.upper() == "MEMORY.MD":
        return JSONResponse({"error": "Invalid filename"}, status_code=400)
    fpath = mem_dir / fname
    if not str(fpath.resolve()).startswith(str(mem_dir.resolve()) + os.sep):
        return JSONResponse({"error": "Invalid path"}, status_code=400)
    if fpath.exists():
        try:
            fpath.unlink()
        except Exception:
            logger.exception("Failed to delete memory topic file")
            return JSONResponse({"error": "Failed to delete"}, status_code=500)
    return JSONResponse({"ok": True})


# --- Context files: the canonical set Codex reads on this host ---
#
# NB: this module uses `from __future__ import annotations`, so a body model must
# be defined ABOVE the route that annotates it — otherwise FastAPI cannot resolve
# the string annotation at registration time and silently demotes it to a query
# parameter.
class ContextFileBody(BaseModel):
    name: str        # registry id, not a path
    content: str


#
# There is one primary AGENTS.md plus a handful of reference docs it points at.
# This registry is fixed on purpose: the UI edits these files in place and offers
# no way to create arbitrary sidecar context files. Every extra file either costs
# context on every session or quietly drifts because nothing ever reads it.
#
# "auto" files are injected into every session's context; "ondemand" files cost
# nothing until AGENTS.md sends a session to them.
_CONTEXT_FILES = [
    {"id": "codex-agents", "paths": [CODEX_HOME / "AGENTS.md"], "load": "auto",
     "label": "$CODEX_HOME/AGENTS.md",
     "note": "Global Codex instructions loaded for every dashboard session."},
    {"id": "home-agents", "paths": [Path.home() / "AGENTS.md"], "load": "auto",
     "label": "~/AGENTS.md",
     "note": "Project-tree instructions for sessions whose working directory is under home."},
    {"id": "github-rules", "paths": [
        Path.home() / "CODEX_GITHUB_RULES.md",
        Path.home() / "CLAUDE_GITHUB_RULES.md",
    ], "load": "ondemand",
     "note": "Git and GitHub rules."},
    {"id": "api-keys", "paths": [
        Path.home() / "CODEX_API_KEYS.md",
        Path.home() / "CLAUDE_API_KEYS.md",
    ], "load": "ondemand",
     "secret": True,
     "note": "Raw API key file. Prefer Settings → APIs, which also shows live usage."},
    {"id": "full-context", "paths": [
        Path.home() / "CODEX_FULL_CONTEXT.md",
        Path.home() / "CLAUDE_FULL_CONTEXT.md",
    ], "load": "ondemand", "secret": True,
     "note": "Complete generated environment, development-system, and settings snapshot."},
    {"id": "infra-index", "paths": [
        CODEX_HOME / "vm_projects_dir.md",
        Path.home() / ".claude" / "vm_projects_dir.md",
    ], "load": "ondemand",
     "note": "Infrastructure index: VMs, domains, and pointers to the per-host detail files."},
    {"id": "droplets", "paths": [Path.home() / "claude_droplets_access.md"], "load": "ondemand",
     "note": "SSH access to the legacy DigitalOcean droplets."},
    {"id": "infra-keeper", "paths": [
        MESSAGES_DIR / "skills" / "_global" / "infra-directory-keeper.md",
    ],
     "load": "ondemand", "note": "Rules for keeping the infrastructure index current."},
    {"id": "browser-qa", "paths": [
        MESSAGES_DIR / "skills" / "_global" / "browser-qa.md",
    ],
     "load": "ondemand", "note": "agent-browser QA procedure to run after a large change."},
    {"id": "legacy-claude", "paths": [Path.home() / "CLAUDE.md"], "load": "legacy",
     "label": "~/CLAUDE.md (legacy)",
     "note": "Legacy Claude context retained for migration reference; Codex does not auto-load it."},
]

_INFRA_DETAIL_DIRS = [CODEX_HOME / "infra", Path.home() / ".claude" / "infra"]


def _first_existing_path(paths: list[Path]) -> Path:
    """Return the first existing candidate, or the preferred path if none exist."""
    return next((path for path in paths if path.exists()), paths[0])


def _context_file_entries():
    """Resolve fixed registry candidates plus existing per-host infra details."""
    entries = []
    for configured in _CONTEXT_FILES:
        entry = dict(configured)
        candidates = list(entry.pop("paths"))
        entry["path"] = _first_existing_path(candidates)
        entries.append(entry)
    try:
        infra_dir = _first_existing_path(list(_INFRA_DETAIL_DIRS))
        for p in sorted(infra_dir.glob("*.md")):
            entries.append({
                "id": "infra-" + p.stem, "path": p, "load": "ondemand",
                "label": "infra/" + p.name,
                "note": ("One line per infrastructure change, newest first."
                         if p.name == "CHANGELOG.md"
                         else "Per-host infrastructure detail, linked from the index."),
            })
    except Exception:
        logger.debug("Failed to list infra detail files", exc_info=True)
    return entries


@app.get("/api/context-files")
async def api_list_context_files(request: Request):
    if not _is_admin(_current_user(request)):
        return JSONResponse({"error": "Admin only"}, status_code=403)
    files = []
    for e in _context_file_entries():
        p = e["path"]
        try:
            exists = p.exists()
            content = p.read_text(errors="replace") if exists else ""
            size = p.stat().st_size if exists else 0
        except Exception:
            logger.debug("Failed to read context file %s", p, exc_info=True)
            continue
        files.append({
            "id": e["id"], "name": e.get("label") or p.name, "path": str(p),
            "load": e["load"], "note": e["note"], "secret": bool(e.get("secret")),
            "content": content, "size": size, "exists": exists,
        })
    auto = sum(f["size"] for f in files if f["load"] == "auto")
    return JSONResponse({"files": files, "auto_bytes": auto})


@app.post("/api/context-files")
async def api_save_context_file(request: Request, body: ContextFileBody):
    """Save one registry file in place. `name` carries the registry id — the path
    is never taken from the client, so there is nothing to traverse."""
    if not _is_admin(_current_user(request)):
        return JSONResponse({"error": "Admin only"}, status_code=403)
    entry = next((e for e in _context_file_entries() if e["id"] == body.name), None)
    if entry is None:
        return JSONResponse({"error": "Unknown context file"}, status_code=404)
    p = entry["path"]
    try:
        existing = p.read_text() if p.exists() else None
        if existing != body.content:
            _backup_before_dashboard_write(p)
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_text(body.content)
        if entry.get("secret"):
            try:
                os.chmod(p, 0o600)
            except Exception:
                logger.debug("chmod 600 failed for %s", p, exc_info=True)
        return JSONResponse({"ok": True, "id": entry["id"], "size": p.stat().st_size})
    except Exception:
        logger.exception("Failed to save context file %s", p)
        return JSONResponse({"error": "Failed to save file"}, status_code=500)


# --- Skills file management ---
#
# There are three layers:
#   1. Library:  ~/.tmux-dashboard/skill-library/<name>/SKILL.md
#                Canonical user-authored skills with YAML frontmatter
#                (name + description). This is the source of truth.
#   2. Active:   ~/.codex/skills/<name>/SKILL.md
#                Global skills loaded by every dashboard session. Library
#                skills are symlinked here when enabled.
#   3. Built-ins: bundled into the Codex binary itself. Always present,
#                not configurable. Listed via /api/builtin-skills
#                so the UI can surface them as read-only.

SKILLS_DIR = MESSAGES_DIR / "skills"
SKILL_LIBRARY_DIR = MESSAGES_DIR / "skill-library"

_SKILL_FILENAME_RE = re.compile(r"^[a-zA-Z0-9_-]+\.md$")
_SKILL_DIR_NAME_RE = re.compile(r"^[a-zA-Z0-9][a-zA-Z0-9_-]{0,63}$")

# Built-in skills bundled with Codex itself. Always available; cannot be
# disabled. Surfaced to the UI as a read-only "Built-in" section
# so users understand which skills are available without any configuration.
_BUILTIN_SKILLS = [
    {"name": "imagegen", "description": "Generate and edit images with OpenAI image models."},
    {"name": "openai-docs", "description": "Look up OpenAI / Codex documentation."},
    {"name": "plugin-creator", "description": "Scaffold a new Codex plugin."},
    {"name": "skill-creator", "description": "Create a new Codex skill (SKILL.md) interactively."},
    {"name": "skill-installer", "description": "Install or manage Codex skills."},
]


def _sanitize_skill_filename(name: str) -> str:
    """Sanitize and validate a flat .md skill filename (legacy session/profile flat-file API)."""
    name = os.path.basename(name)
    if not name.endswith(".md"):
        name += ".md"
    if not _SKILL_FILENAME_RE.match(name):
        return ""
    return name


def _sanitize_skill_dir_name(name: str) -> str:
    """Sanitize a skill directory name (the canonical Skill `<name>`)."""
    name = os.path.basename((name or "").strip())
    if name.endswith(".md"):
        name = name[:-3]
    if not _SKILL_DIR_NAME_RE.match(name):
        return ""
    return name


def _parse_skill_frontmatter(skill_md_path: Path) -> dict:
    """Extract `name` and `description` from a SKILL.md YAML frontmatter block.

    Falls back to the parent directory name when frontmatter is missing or malformed.
    """
    out = {"name": skill_md_path.parent.name, "description": ""}
    try:
        text = skill_md_path.read_text()
    except Exception:
        return out
    if not text.startswith("---"):
        return out
    # Find the closing fence
    end = text.find("\n---", 3)
    if end == -1:
        return out
    block = text[3:end]
    for raw in block.splitlines():
        line = raw.strip()
        if line.startswith("name:"):
            v = line.split(":", 1)[1].strip().strip('"').strip("'")
            if v:
                out["name"] = v
        elif line.startswith("description:"):
            v = line.split(":", 1)[1].strip().strip('"').strip("'")
            if v:
                out["description"] = v
    return out


def _read_skill_dir(d: Path) -> dict | None:
    """Read a skill directory; return metadata dict or None if not a valid skill."""
    if not d.is_dir():
        return None
    skill_md = d / "SKILL.md"
    if not skill_md.is_file():
        return None
    fm = _parse_skill_frontmatter(skill_md)
    try:
        content = skill_md.read_text()
    except Exception:
        content = ""
    return {
        "name": fm["name"],
        "dir_name": d.name,
        "description": fm["description"],
        "path": str(skill_md),
        "content": content,
    }


def _list_library_skills() -> list:
    """List all skills in the library (sorted by directory name)."""
    SKILL_LIBRARY_DIR.mkdir(parents=True, exist_ok=True)
    out = []
    for entry in sorted(SKILL_LIBRARY_DIR.iterdir()):
        info = _read_skill_dir(entry)
        if info:
            out.append(info)
    return out


def _profile_skills_dir(profile_id: str) -> Path:
    """Return the skills/ directory for a given profile, creating it if needed."""
    d = _profile_dir(profile_id) / "skills"
    d.mkdir(parents=True, exist_ok=True)
    return d


def _is_library_link(skills_dir: Path, skill_dir_name: str) -> bool:
    """Return True iff `skills_dir/skill_dir_name` is a symlink to the library copy."""
    target = skills_dir / skill_dir_name
    if not target.is_symlink():
        return False
    try:
        resolved = target.resolve()
    except Exception:
        return False
    expected = (SKILL_LIBRARY_DIR / skill_dir_name).resolve()
    return resolved == expected


def _skill_dir_for_session(session_name: str) -> Path:
    d = SKILLS_DIR / session_name
    d.mkdir(parents=True, exist_ok=True)
    return d


class SkillFileBody(BaseModel):
    name: str
    content: str


class SaveLibrarySkillBody(BaseModel):
    description: str = ""
    content: str


class SkillLibraryBody(BaseModel):
    name: str
    session_name: str = ""


@app.get("/api/sessions/{session_name}/skills")
async def api_list_skills(session_name: str):
    """List .md skill files for a session."""
    _, sess = _find_session(session_name)
    if not sess:
        return JSONResponse({"error": "Session not found"}, status_code=404)
    d = _skill_dir_for_session(session_name)
    files = []
    for p in sorted(d.iterdir()):
        if p.suffix == ".md" and p.is_file():
            try:
                content = p.read_text()
                stat = p.stat()
                files.append({
                    "name": p.name,
                    "content": content,
                    "size": stat.st_size,
                    "modified": stat.st_mtime,
                })
            except Exception:
                logger.debug("Failed to read skill file %s", p, exc_info=True)
    return JSONResponse({"files": files, "path": str(d)})


@app.post("/api/sessions/{session_name}/skills")
async def api_save_skill(session_name: str, body: SkillFileBody):
    """Create or update a skill .md file."""
    _, sess = _find_session(session_name)
    if not sess:
        return JSONResponse({"error": "Session not found"}, status_code=404)
    fname = _sanitize_skill_filename(body.name)
    if not fname:
        return JSONResponse({"error": "Invalid filename. Use alphanumeric, hyphens, underscores with .md extension."}, status_code=400)
    d = _skill_dir_for_session(session_name)
    fpath = d / fname
    # Resolve to prevent traversal
    if not str(fpath.resolve()).startswith(str(d.resolve())):
        return JSONResponse({"error": "Invalid path"}, status_code=400)
    try:
        fpath.write_text(body.content)
        return JSONResponse({"ok": True, "name": fname, "path": str(fpath)})
    except Exception:
        logger.exception("Failed to save skill file")
        return JSONResponse({"error": "Failed to save skill file"}, status_code=500)


@app.delete("/api/sessions/{session_name}/skills/{filename}")
async def api_delete_skill(session_name: str, filename: str):
    """Delete a skill .md file."""
    _, sess = _find_session(session_name)
    if not sess:
        return JSONResponse({"error": "Session not found"}, status_code=404)
    fname = _sanitize_skill_filename(filename)
    if not fname:
        return JSONResponse({"error": "Invalid filename"}, status_code=400)
    d = _skill_dir_for_session(session_name)
    fpath = d / fname
    if not str(fpath.resolve()).startswith(str(d.resolve())):
        return JSONResponse({"error": "Invalid path"}, status_code=400)
    if not fpath.exists():
        return JSONResponse({"error": "File not found"}, status_code=404)
    try:
        fpath.unlink()
        return JSONResponse({"ok": True})
    except Exception:
        logger.exception("Failed to delete skill file")
        return JSONResponse({"error": "Failed to delete skill file"}, status_code=500)


@app.get("/api/skill-library")
async def api_list_skill_library():
    """List all skills in the library with their frontmatter metadata."""
    return JSONResponse({"skills": _list_library_skills()})


@app.get("/api/skill-library/{skill_name}")
async def api_get_library_skill(skill_name: str):
    """Return the SKILL.md content + metadata for a single library skill."""
    name = _sanitize_skill_dir_name(skill_name)
    if not name:
        return JSONResponse({"error": "Invalid skill name"}, status_code=400)
    info = _read_skill_dir(SKILL_LIBRARY_DIR / name)
    if not info:
        return JSONResponse({"error": "Skill not found"}, status_code=404)
    return JSONResponse(info)


@app.post("/api/skill-library/{skill_name}")
async def api_save_library_skill(skill_name: str, body: SaveLibrarySkillBody):
    """Create or update a library skill.

    Body content is the raw SKILL.md text. If it already starts with a `---`
    frontmatter block, it is trusted as-is. Otherwise we synthesize a frontmatter
    block from `skill_name` and `description`.
    """
    name = _sanitize_skill_dir_name(skill_name)
    if not name:
        return JSONResponse({"error": "Invalid skill name (alphanumeric, hyphens, underscores; max 64 chars)"}, status_code=400)
    desc = (body.description or "").strip().replace("\n", " ").replace("\r", " ")
    raw = (body.content or "").lstrip()
    if raw.startswith("---"):
        full = raw if raw.endswith("\n") else raw + "\n"
    else:
        full = f"---\nname: {name}\ndescription: {desc}\n---\n\n{raw.rstrip()}\n"
    d = SKILL_LIBRARY_DIR / name
    try:
        d.mkdir(parents=True, exist_ok=True)
        (d / "SKILL.md").write_text(full)
    except Exception:
        logger.exception("Failed to save library skill")
        return JSONResponse({"error": "Failed to save skill"}, status_code=500)
    return JSONResponse({"ok": True, "name": name})


@app.delete("/api/skill-library/{skill_name}")
async def api_delete_library_skill(skill_name: str):
    """Delete a library skill (and break any per-profile symlinks pointing to it)."""
    name = _sanitize_skill_dir_name(skill_name)
    if not name:
        return JSONResponse({"error": "Invalid skill name"}, status_code=400)
    d = SKILL_LIBRARY_DIR / name
    if not d.is_dir():
        return JSONResponse({"error": "Skill not found"}, status_code=404)
    # Sweep all profile skills/ dirs and remove dangling/library-pointing symlinks
    try:
        for profile in _load_roles().get("profiles", []):
            pid = profile.get("id")
            if not pid or pid == DEFAULT_PROFILE_ID:
                continue
            sd = _profile_dir(pid) / "skills"
            link = sd / name
            if link.is_symlink():
                try:
                    link.unlink()
                except Exception:
                    logger.debug("Failed to clean up profile symlink %s", link, exc_info=True)
    except Exception:
        logger.debug("Failed to sweep profile symlinks for deleted skill", exc_info=True)
    try:
        shutil.rmtree(str(d))
    except Exception:
        logger.exception("Failed to delete library skill")
        return JSONResponse({"error": "Failed to delete skill"}, status_code=500)
    return JSONResponse({"ok": True})


@app.get("/api/builtin-skills")
async def api_list_builtin_skills():
    """Return the list of skills bundled with Codex itself (read-only)."""
    return JSONResponse({"skills": list(_BUILTIN_SKILLS)})


# --- Standard Codex settings (legacy profile-shaped persistence) ---

ROLES_FILE = MESSAGES_DIR / "codex-roles.json"
DEFAULT_PROFILE_ID = "default"
_PROFILE_ID_RE = re.compile(r"^[a-z0-9][a-z0-9_-]{0,31}$")
_RESERVED_PROFILE_IDS = {DEFAULT_PROFILE_ID}

# Common permissions and environment baseline kept in the legacy default record.
_COMMON_PERMISSIONS = {
    "defaultMode": "bypassPermissions",
    "allow": ["*"],
    "deny": [],
}
_COMMON_ENV = {
    "DISABLE_AUTOUPDATER": "0",
    "DISABLE_TELEMETRY": "1",
    "BASH_DEFAULT_TIMEOUT_MS": "120000",
    "BASH_MAX_TIMEOUT_MS": "600000",
}

# Role-specific presets are retired; all sessions use the standard Codex home.
_PROFILE_PRESETS: list[dict] = []


def _default_profile_record() -> dict:
    return {"id": DEFAULT_PROFILE_ID, "name": "Default", "model": "",
            "effort": "",
            "permissions": dict(_COMMON_PERMISSIONS),
            "env": dict(_COMMON_ENV),
            "codex_md": "", "memory_md": "", "builtin": True}


def _save_roles(data: dict):
    try:
        MESSAGES_DIR.mkdir(parents=True, exist_ok=True)
        ROLES_FILE.write_text(json.dumps(data, indent=2))
    except Exception:
        logger.exception("Failed to save %s", ROLES_FILE)


_PRESET_FIELDS = ("model", "effort", "permissions", "env", "codex_md", "memory_md", "seed_skills")


def _refresh_builtin_presets(data: dict) -> bool:
    """Bring built-in preset entries up-to-date with `_PROFILE_PRESETS` content.

    Only touches profiles where `builtin: True` AND `edited` is falsy. New presets
    that weren't in the file yet are appended. The default profile is also
    refreshed from `_default_profile_record()`. Returns True if any change.
    """
    changed = False
    by_id = {p["id"]: p for p in data["profiles"]}
    # Refresh the default record (treating _default_profile_record() as its preset)
    default_existing = by_id.get(DEFAULT_PROFILE_ID)
    if default_existing is not None and not default_existing.get("edited"):
        default_template = _default_profile_record()
        for field in _PRESET_FIELDS:
            new_val = default_template.get(field) if field in default_template else None
            if default_existing.get(field) != new_val:
                if new_val is None:
                    default_existing.pop(field, None)
                else:
                    default_existing[field] = new_val
                changed = True
    for preset in _PROFILE_PRESETS:
        existing = by_id.get(preset["id"])
        if existing is None:
            data["profiles"].append({**preset, "builtin": True})
            changed = True
            continue
        if not existing.get("builtin") or existing.get("edited"):
            continue
        for field in _PRESET_FIELDS:
            new_val = preset.get(field) if field in preset else None
            if existing.get(field) != new_val:
                if new_val is None:
                    existing.pop(field, None)
                else:
                    existing[field] = new_val
                changed = True
        # Don't auto-rename: name is the most user-visible field
    return changed


def _load_roles() -> dict:
    """Load the legacy roles file used to persist the default Codex settings."""
    if not ROLES_FILE.exists():
        data = {
            "profiles": [_default_profile_record()] + [{**p, "builtin": True} for p in _PROFILE_PRESETS],
            "session_profiles": {},
        }
        _save_roles(data)
        return data
    try:
        with open(ROLES_FILE) as f:
            data = json.load(f)
        data.setdefault("profiles", [])
        data.setdefault("session_profiles", {})
        if not any(p.get("id") == DEFAULT_PROFILE_ID for p in data["profiles"]):
            data["profiles"].insert(0, _default_profile_record())
        if _refresh_builtin_presets(data):
            _save_roles(data)
        return data
    except Exception:
        logger.exception("Failed to load %s -- using defaults", ROLES_FILE)
        return {"profiles": [_default_profile_record()], "session_profiles": {}}


def _profile_dir(profile_id: str) -> Path:
    """Filesystem path used for CODEX_HOME for a given profile id."""
    if profile_id == DEFAULT_PROFILE_ID:
        return Path.home() / ".codex"
    return Path.home() / f".codex-{profile_id}"


def _toml_escape(s: str) -> str:
    return s.replace("\\", "\\\\").replace('"', '\\"')


def _render_codex_config_toml(managed: dict) -> str:
    """Render the dashboard-managed slice of a codex config.toml.

    Codex's config.toml uses TOML, not JSON. We only manage the keys we own
    (model, model_reasoning_effort, sandbox_mode, approval_policy) plus a
    [shell_environment_policy.env]
    table for env vars. The top-level [projects.*] tables are user-managed and
    are NOT touched here.
    """
    lines = ["# Managed by codex-dashboard. Edits to keys below may be overwritten."]
    if managed.get("model"):
        lines.append(f'model = "{_toml_escape(managed["model"])}"')
    if managed.get("model_reasoning_effort"):
        lines.append(
            f'model_reasoning_effort = "{_toml_escape(managed["model_reasoning_effort"])}"'
        )
    if managed.get("sandbox_mode"):
        lines.append(f'sandbox_mode = "{_toml_escape(managed["sandbox_mode"])}"')
    if managed.get("approval_policy"):
        lines.append(f'approval_policy = "{_toml_escape(managed["approval_policy"])}"')
    env = managed.get("env") or {}
    if env:
        lines.append("")
        lines.append("[shell_environment_policy.env]")
        for k, v in env.items():
            lines.append(f'{_toml_escape(k)} = "{_toml_escape(str(v))}"')
    return "\n".join(lines) + "\n"


def _backup_before_dashboard_write(path: Path):
    """Back up an existing file before the dashboard overwrites it."""
    if not path.exists():
        return
    try:
        backup = path.with_name(f"{path.name}.bak-dashboard-{int(time.time() * 1000)}")
        shutil.copy2(path, backup)
    except Exception:
        logger.debug("Failed to back up %s before dashboard write", path, exc_info=True)


def _merge_top_level_toml_keys(existing: str, managed: dict) -> str:
    """Merge dashboard-managed top-level TOML keys without touching sections."""
    managed_keys = ("model", "model_reasoning_effort", "sandbox_mode", "approval_policy")
    updates = {key: str(managed[key]) for key in managed_keys if managed.get(key)}
    if not updates:
        return existing if existing.endswith("\n") else existing + "\n"

    def render_line(key: str) -> str:
        return f'{key} = "{_toml_escape(updates[key])}"'

    out: list[str] = []
    written: set[str] = set()
    in_section = False
    inserted_before_sections = False
    for line in existing.splitlines():
        stripped = line.strip()
        if stripped.startswith("[") and stripped.endswith("]"):
            if not inserted_before_sections:
                for key in managed_keys:
                    if key in updates and key not in written:
                        out.append(render_line(key))
                        written.add(key)
                inserted_before_sections = True
            in_section = True
            out.append(line)
            continue
        if not in_section and "=" in stripped and not stripped.startswith("#"):
            key = stripped.split("=", 1)[0].strip()
            if key in updates:
                out.append(render_line(key))
                written.add(key)
                continue
        out.append(line)
    if not inserted_before_sections:
        if out and out[-1].strip():
            out.append("")
        for key in managed_keys:
            if key in updates and key not in written:
                out.append(render_line(key))
                written.add(key)
    return "\n".join(out).rstrip() + "\n"


def _ensure_codex_project_trust(existing: str, project_dir: str) -> str:
    """Persist Codex's native trust marker for the detached-session workdir.

    Interactive Codex asks whether a directory is trusted before showing its
    prompt. Detached tmux sessions cannot safely complete that onboarding flow,
    so every dashboard-managed CODEX_HOME explicitly trusts the directory from
    which the dashboard launches Codex. Other project and MCP sections remain
    untouched.
    """
    project = str(Path(project_dir).expanduser().resolve())
    header = f'[projects."{_toml_escape(project)}"]'
    lines = existing.splitlines()
    section_start = next(
        (index for index, line in enumerate(lines) if line.strip() == header),
        None,
    )
    if section_start is None:
        if lines and lines[-1].strip():
            lines.append("")
        lines.extend((header, 'trust_level = "trusted"'))
        return "\n".join(lines).rstrip() + "\n"

    section_end = next(
        (
            index
            for index in range(section_start + 1, len(lines))
            if lines[index].strip().startswith("[")
            and lines[index].strip().endswith("]")
        ),
        len(lines),
    )
    trust_line = re.compile(r"^\s*trust_level\s*=")
    matches = [
        index
        for index in range(section_start + 1, section_end)
        if trust_line.match(lines[index])
    ]
    if matches:
        first = matches[0]
        lines[first] = 'trust_level = "trusted"'
        for duplicate in reversed(matches[1:]):
            del lines[duplicate]
    else:
        lines.insert(section_start + 1, 'trust_level = "trusted"')
    return "\n".join(lines).rstrip() + "\n"


def _materialize_profile(profile: dict):
    """Write config.toml, AGENTS.md, MEMORY.md, and ensure skills/ exists.

    For non-default profiles: config.toml is fully owned by the dashboard and
    the current OpenAI key is mirrored into the profile's auth.json so codex
    authenticates when CODEX_HOME points here.

    For the default profile (~/.codex): merge only dashboard-managed top-level
    keys, preserving project/MCP sections. Back up before every managed write.
    """
    pid = profile["id"]
    d = _profile_dir(pid)
    d.mkdir(parents=True, exist_ok=True)
    (d / "skills").mkdir(parents=True, exist_ok=True)
    is_default = (pid == DEFAULT_PROFILE_ID)

    config_path = d / "config.toml"
    codexmd_path = d / "AGENTS.md"
    memorymd_path = d / "MEMORY.md"

    # Compose the dashboard-managed slice
    managed: dict = {}
    if profile.get("model"):
        managed["model"] = profile["model"]
    if profile.get("effort"):
        managed["model_reasoning_effort"] = profile["effort"]
    # Sensible codex defaults for unattended use.
    managed["sandbox_mode"] = profile.get("sandbox_mode") or "danger-full-access"
    managed["approval_policy"] = profile.get("approval_policy") or "never"
    env = dict(profile.get("env") or {})
    if env:
        managed["env"] = env

    try:
        if is_default:
            existing = config_path.read_text() if config_path.exists() else ""
            merged = _merge_top_level_toml_keys(existing, managed)
            merged = _ensure_codex_project_trust(merged, os.getcwd())
            if merged != existing:
                _backup_before_dashboard_write(config_path)
                config_path.write_text(merged)
        else:
            rendered = _render_codex_config_toml(managed)
            rendered = _ensure_codex_project_trust(rendered, os.getcwd())
            existing = config_path.read_text() if config_path.exists() else ""
            if rendered != existing:
                _backup_before_dashboard_write(config_path)
                config_path.write_text(rendered)
            # Mirror the current OpenAI key so codex authenticates in this
            # isolated CODEX_HOME (it reads <dir>/auth.json).
            try:
                key = _stored_openai_key or OPENAI_API_KEY
                src_auth = CODEX_HOME / "auth.json"
                if not key and src_auth.exists():
                    try:
                        key = json.loads(src_auth.read_text()).get("OPENAI_API_KEY", "")
                    except Exception:
                        key = ""
                if key:
                    auth_path = d / "auth.json"
                    auth_path.write_text(json.dumps({"auth_mode": "apikey", "OPENAI_API_KEY": key}, indent=2))
                    auth_path.chmod(0o600)
            except Exception:
                logger.debug("Failed to mirror auth.json into profile %s", pid, exc_info=True)
        codex_content = profile.get("codex_md") or ""
        memory_content = profile.get("memory_md") or ""
        # The default profile lives directly in ~/.codex, where AGENTS.md and
        # MEMORY.md are global user-owned context.  Built-in role records carry
        # empty placeholders for these fields, so treating an empty placeholder
        # as authoritative would erase the global files during an unrelated
        # model/effort change.  A non-empty value is still an explicit dashboard
        # edit; isolated profiles remain fully owned and therefore keep the
        # existing empty-file behaviour.
        write_codex_context = not is_default or bool(codex_content)
        write_memory_context = not is_default or bool(memory_content)
        if write_codex_context and (
            not codexmd_path.exists() or codexmd_path.read_text() != codex_content
        ):
            _backup_before_dashboard_write(codexmd_path)
            codexmd_path.write_text(codex_content)
        if write_memory_context and (
            not memorymd_path.exists() or memorymd_path.read_text() != memory_content
        ):
            _backup_before_dashboard_write(memorymd_path)
            memorymd_path.write_text(memory_content)
        # Seed initial skill files only when they are missing -- never overwrite,
        # so the user (or a fresh `agent-browser skills get` pull) can edit them.
        seed_skills = profile.get("seed_skills") or []
        if seed_skills:
            skills_root = d / "skills"
            for entry in seed_skills:
                rel = (entry.get("path") or "").lstrip("/").replace("\\", "/")
                content = entry.get("content") or ""
                if not rel:
                    continue
                target = (skills_root / rel).resolve()
                # Path traversal guard
                try:
                    target.relative_to(skills_root.resolve())
                except ValueError:
                    logger.warning("Skipping seed skill outside skills dir: %s", rel)
                    continue
                if target.exists():
                    continue
                target.parent.mkdir(parents=True, exist_ok=True)
                target.write_text(content)
    except Exception:
        logger.exception("Failed to materialize profile %s at %s", pid, d)


def _find_profile(profile_id: str, data: dict | None = None):
    if data is None:
        data = _load_roles()
    for p in data["profiles"]:
        if p["id"] == profile_id:
            return p
    return None


def _get_session_profile_id(session_name: str) -> str:
    """Compatibility shim: role profiles are retired, so every session is default."""
    return DEFAULT_PROFILE_ID


# Ensure the compatibility roles file has its default record. Retired role
# profiles are deliberately not materialized into separate CODEX_HOME trees.
try:
    _load_roles()
except Exception:
    logger.exception("Failed to initialize the default Codex configuration")


def _profile_summary(p: dict) -> dict:
    return {
        "id": p["id"], "name": p.get("name", p["id"]),
        "model": p.get("model", ""), "effort": p.get("effort", ""),
        "builtin": bool(p.get("builtin")),
    }


def _retired_role_profile_response(profile_id: str) -> JSONResponse | None:
    if profile_id == DEFAULT_PROFILE_ID:
        return None
    return JSONResponse(
        {"error": "Role profiles have been removed; all sessions use the standard Codex home."},
        status_code=410,
    )


def _normalize_reasoning_effort(effort: str | None) -> str | None:
    value = (effort or "").strip().lower()
    if not value:
        return ""
    value = _CODEX_REASONING_EFFORT_ALIASES.get(value, value)
    if value not in _CODEX_REASONING_EFFORTS:
        return None
    return value


